using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;
namespace ROM.Tutorial.Crilium.Editor {
public static class CriliumDesertVisuals {
 const string Art="Assets/ROM/Tutorial/Crilium/Art/";static string Output=>Path.GetFullPath("Logs/CreliumDesertVisuals20261025");
 static Material Existing(string name){return AssetDatabase.FindAssets(name+" t:Material",new[]{"Assets/Standard Assets/Sun_Temple"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>Path.GetFileNameWithoutExtension(p)==name).Select(AssetDatabase.LoadAssetAtPath<Material>).First();}
 static Material Own(string name,Material source){string path=Art+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(source);AssetDatabase.CreateAsset(m,path);}return m;}
 static void Tint(Material m,Color tint){if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",tint);else if(m.HasProperty("_Color"))m.SetColor("_Color",tint);EditorUtility.SetDirty(m);}
 static Material Glow(string name,Color tint){var m=AssetDatabase.LoadAssetAtPath<Material>(Art+name+".mat");if(!m){var shader=Shader.Find("Universal Render Pipeline/Unlit");if(!shader)throw new Exception("Existing URP particle shader unavailable");m=new Material(shader);AssetDatabase.CreateAsset(m,Art+name+".mat");}m.shader=Shader.Find("Universal Render Pipeline/Unlit");m.SetFloat("_Surface",1);m.SetFloat("_Blend",0);m.SetInt("_SrcBlend",(int)BlendMode.SrcAlpha);m.SetInt("_DstBlend",(int)BlendMode.OneMinusSrcAlpha);m.SetInt("_ZWrite",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.renderQueue=3000;Tint(m,tint);if(m.HasProperty("_BaseMap"))m.SetTexture("_BaseMap",Texture2D.whiteTexture);return m;}
 static GameObject Cube(string name,Transform root,Vector3 local,Vector3 size,Material material){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(root,false);go.transform.localPosition=local;go.transform.localScale=size;UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());go.GetComponent<Renderer>().sharedMaterial=material;return go;}
 static void ReplaceRoot(string name){var old=GameObject.Find(name);if(old)UnityEngine.Object.DestroyImmediate(old);}
 static LineRenderer Line(Transform root,string name,Material material,int points,bool loop){var line=new GameObject(name).AddComponent<LineRenderer>();line.transform.SetParent(root,false);line.sharedMaterial=material;line.useWorldSpace=false;line.positionCount=points;line.loop=loop;line.numCornerVertices=2;line.numCapVertices=2;line.startColor=Color.white;line.endColor=new Color(1,.4f,.45f,.12f);line.shadowCastingMode=ShadowCastingMode.Off;line.receiveShadows=false;return line;}
 [MenuItem("ROM/Crilium/Apply Crelium desert sky and blood monument")]
 public static void Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play before visual edit");Directory.CreateDirectory(Art);Directory.CreateDirectory(Output);AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene(CriliumSession.ScenePath,OpenSceneMode.Single);if(scene.name!="Crilium")throw new Exception("Wrong scene");
  var sky=Own("CreliumDustSky",Existing("Sky_MediumCloudy"));sky.SetColor("_Color",new Color(.92f,.8f,.65f,1));sky.SetFloat("_Exposure",1.15f);sky.SetFloat("_FogColorMix",.45f);sky.SetFloat("_Rotation",145);RenderSettings.skybox=sky;RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogColor=new Color(.59f,.43f,.31f);RenderSettings.fogDensity=.00085f;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.43f,.39f,.35f);RenderSettings.ambientEquatorColor=new Color(.55f,.41f,.28f);RenderSettings.ambientGroundColor=new Color(.2f,.15f,.13f);RenderSettings.reflectionIntensity=.55f;var sun=GameObject.Find("Crilium sunlight").GetComponent<Light>();sun.color=new Color(1,.87f,.7f);sun.intensity=1.15f;sun.transform.rotation=Quaternion.Euler(27,-32,0);RenderSettings.sun=sun;EditorUtility.SetDirty(sky);
  var sand=Own("CreliumOchreGround",Existing("Dirt_Tiling"));Tint(sand,new Color(.94f,.9f,.8f));if(sand.HasProperty("_BaseMap"))sand.SetTextureScale("_BaseMap",new Vector2(7,7));
  foreach(var tr in GameObject.Find("Crilium organic route").GetComponentsInChildren<Transform>())if(tr.name=="Walkable foundation")tr.GetComponent<Renderer>().sharedMaterial=sand;
  ReplaceRoot("Crelium distant desert and monument");var scenery=new GameObject("Crelium distant desert and monument");var ground=GameObject.CreatePrimitive(PrimitiveType.Plane);ground.name="Distant desert visual only";ground.transform.SetParent(scenery.transform);ground.transform.position=new Vector3(0,-8,450);ground.transform.localScale=new Vector3(200,1,200);UnityEngine.Object.DestroyImmediate(ground.GetComponent<Collider>());ground.GetComponent<Renderer>().sharedMaterial=sand;
  for(int n=0;n<3;n++){var dune=GameObject.CreatePrimitive(PrimitiveType.Sphere);dune.name="Distant dune visual only "+n;dune.transform.SetParent(scenery.transform);dune.transform.position=n==0?new Vector3(-130,-12,1130):n==1?new Vector3(110,-12,1200):new Vector3(-10,-16,1330);dune.transform.localScale=new Vector3(260,30,180);UnityEngine.Object.DestroyImmediate(dune.GetComponent<Collider>());dune.GetComponent<Renderer>().sharedMaterial=sand;dune.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;}

  var stone=Own("CreliumMonumentSandstone",Existing("Bricks_Solid"));Tint(stone,new Color(.93f,.84f,.64f));if(stone.HasProperty("_BaseMap"))stone.SetTextureScale("_BaseMap",new Vector2(8,3));if(stone.HasProperty("_Smoothness"))stone.SetFloat("_Smoothness",.12f);
  var monument=new GameObject("Planetary heart pyramid - distant landmark").transform;monument.SetParent(scenery.transform);monument.position=new Vector3(-30,-8,1250);
  for(int n=0;n<20;n++){float width=220*(1-n/20f);Cube("Stone terrace "+(n+1),monument,new Vector3(0,n*7.5f+3.75f,0),new Vector3(width,7.5f,width),stone);}
  var roofPath=AssetDatabase.FindAssets("Bld_Square_Roof_A t:Prefab",new[]{"Assets/Standard Assets/Sun_Temple"}).Select(AssetDatabase.GUIDToAssetPath).First(p=>Path.GetFileNameWithoutExtension(p)=="Bld_Square_Roof_A");var cap=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(roofPath));cap.name="Existing temple apex";cap.transform.SetParent(monument,false);cap.transform.localPosition=Vector3.up*150;var rs=cap.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var rr in rs)b.Encapsulate(rr.bounds);cap.transform.localScale*=13/Mathf.Max(b.size.x,b.size.z);b=rs[0].bounds;foreach(var rr in rs){b.Encapsulate(rr.bounds);rr.sharedMaterials=rr.sharedMaterials.Select(_=>stone).ToArray();}cap.transform.position+=Vector3.up*(monument.position.y+150-b.min.y);foreach(var c in cap.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);
  var beacon=new GameObject("Blood magic rising into sky").AddComponent<CriliumBloodBeacon>();beacon.transform.SetParent(scenery.transform);beacon.transform.position=monument.position+Vector3.up*155;var core=Glow("CreliumBloodCore",new Color(.72f,.002f,.035f,.92f));var thread=Glow("CreliumBloodStrands",new Color(.9f,.008f,.045f,.65f));for(int n=6;n<=14;n+=4){var rune=Line(monument,"Discrete crimson glyph "+n,thread,5,true);rune.transform.localPosition=new Vector3(0,n*7.5f+3.75f,-110*(1-n/20f)-.2f);rune.widthMultiplier=.55f;rune.startColor=rune.endColor=new Color(1,1,1,.65f);rune.SetPositions(new[]{new Vector3(0,-2.5f,0),new Vector3(-3,0,0),new Vector3(0,2.5f,0),new Vector3(3,0,0),new Vector3(0,-2.5f,0)});}
  beacon.Streams=new LineRenderer[4];for(int n=0;n<4;n++)beacon.Streams[n]=Line(beacon.transform,"World-space rising current "+n,n==0?core:thread,56,false);beacon.Rings=new LineRenderer[2];for(int n=0;n<2;n++)beacon.Rings[n]=Line(beacon.transform,"Blood orbit "+n,thread,49,true);
  var sparks=new GameObject("Rising blood embers").AddComponent<ParticleSystem>();sparks.transform.SetParent(beacon.transform,false);sparks.transform.localRotation=Quaternion.Euler(-90,0,0);var main=sparks.main;main.loop=true;main.startLifetime=5;main.startSpeed=55;main.startSize=2.6f;main.startColor=new Color(.95f,.06f,.16f,.65f);main.maxParticles=96;main.simulationSpace=ParticleSystemSimulationSpace.Local;var emission=sparks.emission;emission.rateOverTime=12;var shape=sparks.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=5;shape.radius=4;sparks.GetComponent<ParticleSystemRenderer>().sharedMaterial=thread;beacon.Sparks=sparks;beacon.Evaluate(0);
  ConfigureBounds();Canonicalize();EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(Output,"applied.txt"),"CRELIUM visual-only desert sky, distant 20-tier pyramid, animated scene-space blood currents and collision bounds. No original world/Journal modifications.\n");Debug.Log("CRELIUM DESERT VISUALS APPLIED");
 }
 static void ConfigureBounds(){ReplaceRoot("Crelium hidden level limits");var root=new GameObject("Crelium hidden level limits");var border=root.AddComponent<CriliumBounds>();border.Arrival=new Vector3(0,2,0);border.Areas=GameObject.Find("Crilium organic route").GetComponentsInChildren<Transform>().Where(t=>t.name=="Walkable foundation").Select(t=>{var b=t.GetComponent<Collider>().bounds;return Rect.MinMaxRect(b.min.x,b.min.z,b.max.x,b.max.z);}).ToArray();var xs=border.Areas.SelectMany(a=>new[]{a.xMin,a.xMax}).Distinct().OrderBy(x=>x).ToArray();var zs=border.Areas.SelectMany(a=>new[]{a.yMin,a.yMax}).Distinct().OrderBy(x=>x).ToArray();var cells=new bool[xs.Length-1,zs.Length-1];for(int x=0;x<xs.Length-1;x++)for(int z=0;z<zs.Length-1;z++)cells[x,z]=border.Areas.Any(a=>a.Contains(new Vector2((xs[x]+xs[x+1])*.5f,(zs[z]+zs[z+1])*.5f)));
  void Wall(Vector2 a,Vector2 b){var go=new GameObject("Hidden boundary collider");go.transform.SetParent(root.transform);go.transform.position=new Vector3((a.x+b.x)*.5f,14,(a.y+b.y)*.5f);var box=go.AddComponent<BoxCollider>();box.size=new Vector3(Mathf.Max(.65f,Mathf.Abs(b.x-a.x)),32,Mathf.Max(.65f,Mathf.Abs(b.y-a.y)));}
  for(int x=0;x<xs.Length-1;x++)for(int z=0;z<zs.Length-1;z++)if(cells[x,z]){if(x==0||!cells[x-1,z])Wall(new Vector2(xs[x],zs[z]),new Vector2(xs[x],zs[z+1]));if(x==xs.Length-2||!cells[x+1,z])Wall(new Vector2(xs[x+1],zs[z]),new Vector2(xs[x+1],zs[z+1]));if(z==0||!cells[x,z-1])Wall(new Vector2(xs[x],zs[z]),new Vector2(xs[x+1],zs[z]));if(z==zs.Length-2||!cells[x,z+1])Wall(new Vector2(xs[x],zs[z+1]),new Vector2(xs[x+1],zs[z+1]));}
 }
 static void Canonicalize(){var d=CriliumDefinition.Load;if(d){foreach(var lesson in d.Lessons){lesson.Title=lesson.Title.Replace("Crilium","Crelium");lesson.Instruction=lesson.Instruction.Replace("Crilium","Crelium");lesson.Help=lesson.Help.Replace("Crilium","Crelium");}EditorUtility.SetDirty(d);foreach(var q in d.Journal.Quests){q.Description=q.Description.Replace("Crilium","Crelium");EditorUtility.SetDirty(q);}}}
 public static void Capture(){Directory.CreateDirectory(Output);var scene=EditorSceneManager.OpenScene(CriliumSession.ScenePath,OpenSceneMode.Single);var beacon=UnityEngine.Object.FindFirstObjectByType<CriliumBloodBeacon>();if(!beacon)throw new Exception("Beacon missing");beacon.Evaluate(.5f);var before=beacon.Streams[1].GetPosition(25);beacon.Evaluate(2.5f);if(Vector3.Distance(before,beacon.Streams[1].GetPosition(25))<.1f)throw new Exception("Beacon does not animate");beacon.Sparks.Simulate(2,true,true,true);beacon.Sparks.Pause();
  foreach(var m in AssetDatabase.FindAssets("t:Material",new[]{Art}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>)){if(!m.shader||!m.shader.isSupported||ShaderUtil.GetShaderMessages(m.shader).Any(x=>x.severity.ToString()=="Error"))throw new Exception("Unsupported/error material "+m.name);}
  var bounds=UnityEngine.Object.FindFirstObjectByType<CriliumBounds>();if(!bounds||!bounds.Contains(new Vector3(0,1,0))||bounds.Contains(new Vector3(-30,1,540)))throw new Exception("Bounds validation failed");if(GameObject.Find("Crelium distant desert and monument").GetComponentsInChildren<Collider>().Length>0)throw new Exception("Distant landmark must not have interaction/collision");
  Photo("Crelium-04-cielo-y-recorrido-editor.png",new Vector3(8,5,105),new Vector3(-30,85,540),62);Photo("Crelium-05-piramide-y-magia-sangre-editor.png",new Vector3(-190,65,340),new Vector3(-30,175,540),62);Photo("Crelium-06-vista-general-desertica-editor.png",new Vector3(125,100,-65),new Vector3(10,50,190),62);
  File.WriteAllText(Path.Combine(Output,"visual-validation.txt"),"PASS Existing sky shader and all own URP materials supported, no shader compiler errors\nPASS Blood current geometry changes between t0.5 and t2.5\nPASS Distant pyramid has no combat target or collider\nPASS Arrival inside bounds and distant landmark outside\nPASS Three real Unity Editor render captures, not generated concepts\nINFO Actual player jump/leap collision QA pending. Vitral/Saara integration and journal fix remain pending.\n");Debug.Log("CRELIUM VISUAL CAPTURES COMPLETE");
 }
 static void Photo(string file,Vector3 position,Vector3 target,float fov){var go=new GameObject("Temporary Crelium photo camera");var cam=go.AddComponent<Camera>();cam.transform.position=position;cam.transform.LookAt(target);cam.fieldOfView=fov;cam.clearFlags=CameraClearFlags.Skybox;cam.nearClipPlane=.1f;cam.farClipPlane=2000;var rt=new RenderTexture(1920,1080,24);cam.targetTexture=rt;cam.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(1920,1080,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1920,1080),0,0);texture.Apply();File.WriteAllBytes(Path.Combine(Output,file),texture.EncodeToPNG());RenderTexture.active=previous;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(texture);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}
 public static void ApplyAndCapture(){Apply();Capture();}
